double intersection(double  start1, double end1, double start2, double end2) {
    if (start1 <= start2 && end1 > start2) {
        return min(end1, end2) - start2;
    }
​
    if (start1 >= start2 && end2 > start1) {
        return min(end1, end2) - start1;
    }
    return 0;
}
