import (
    "fmt"
    "math"
    "sort"
)
​
// Node 结构体定义
type Node struct {
    id         int
    distance   int
    personCount int
    money      int
    time       int
}
​
// 不同时间段的排队人数变化率
var times = [5][3]float64{
    {8 * 60, 10 * 60, 2},
    {10 * 60, 12 * 60, -0.8},
    {12 * 60, 14 * 60, 9},
    {14 * 60, 18 * 60, -0.8},
    {18 * 60, 20 * 60, 19},
}
​
// 计算两个时间区间的交集时长
func intersection(start1, end1, start2, end2 float64) float64 {
    if start1 <= start2 && end1 > start2 {
        return math.Min(end1, end2) - start2
    }
    if start1 >= start2 && end2 > start1 {
        return math.Min(end1, end2) - start1
    }
    return 0
}
​
// 处理逻辑
func solve(ans []Node, start, end int) {
    var res []Node
​
    for _, node := range ans {
        arrived := start + node.distance*10
        node.money = 10 * node.distance
        // 不可能完成
        if end <= arrived {
            continue
        }

        if arrived < 8*60 {
            // 8点之后才能进行
            arrived = 8 * 60
            node.time = arrived - start + node.personCount
            if node.time+start >= end {
                continue
            }
            res = append(res, node)
            continue
        }
        // 累计到达之前增加的排队人数
        for _, time := range times {
            start2, end2, perSonAddPer := time[0], time[1], time[2]
            t := intersection(float64(start), float64(arrived), start2, end2)
            if t > 0 {
                node.personCount += int(math.Floor(t * perSonAddPer))
                if node.personCount < 0 {
                    node.personCount = 0
                }
            }
        }
​
        node.time = arrived - start + node.personCount
        if node.time+start >= end {
            continue
        }
        res = append(res, node)
    }
​
    fmt.Println(len(res))
    // 自定义排序
    sort.Slice(res, func(i, j int) bool {
        if res[i].time != res[j].time {
            return res[i].time < res[j].time
        }
        if res[i].money != res[j].money {
            return res[i].money < res[j].money
        }
        return res[i].id < res[j].id
    })
​
    for _, node := range res {
        fmt.Println(node.id, node.time, node.money)
    }
}
​
func main() {
    var h1, m1, h2, m2, n int
    fmt.Scan(&h1, &m1)
    fmt.Scan(&h2, &m2)
    fmt.Scan(&n)
​
    ans := make([]Node, n)
    for i := 0; i < n; i++ {
        fmt.Scan(&ans[i].id, &ans[i].distance, &ans[i].personCount)
    }
​
    start := h1*60 + m1
    // 20点之前要完成
    end := int(math.Min(float64(h2*60+m2), 20*60))
​
    solve(ans, start, end)
}
